import{_ as h,C as i,o as d,c as l,a2 as n,j as e,E as o,a as r}from"./chunks/framework.9yf7n3zg.js";const g="/guide/media/homes-and-stories-library.webp",m="/guide/media/homes-and-stories-sidebar-states.webp",u="/guide/media/homes-and-stories-library-empty.webp",c="/guide/media/homes-and-stories-storage.webp",p="/guide/media/homes-and-stories-rename.webp",G=JSON.parse('{"title":"Homes and stories","description":"","frontmatter":{},"headers":[],"relativePath":"guide/homes-and-stories.md","filePath":"guide/homes-and-stories.md","lastUpdated":1791677002000}'),y={name:"guide/homes-and-stories.md"},f={tabindex:"0"},w={style:{"text-align":"center"}},b={style:{"text-align":"center"}},k={style:{"text-align":"center"}},S={style:{"text-align":"center"}},v={style:{"text-align":"center"}},T={style:{"text-align":"center"}},L={style:{"text-align":"center"}},x={style:{"text-align":"center"}},q={style:{"text-align":"center"}},P={style:{"text-align":"center"}},A={style:{"text-align":"center"}},N={style:{"text-align":"center"}},_={style:{"text-align":"center"}},D={style:{"text-align":"center"}},W={style:{"text-align":"center"}},O={style:{"text-align":"center"}},C={style:{"text-align":"center"}};function R(I,t,V,Y,j,F){const s=i("Dot"),a=i("Clip");return d(),l("div",null,[t[29]||(t[29]=n('<h1 id="homes-and-stories" tabindex="-1">Homes and stories <a class="header-anchor" href="#homes-and-stories" aria-label="Permalink to &quot;Homes and stories&quot;">​</a></h1><p>A writing home is the folder that holds your stories. This page says what a home is, what Leathercase keeps in it, how the Library shows its stories, how to have more than one home, how to remove one, and what happens when you rename a note in your own writing app.</p><p>Keys are written for Windows and Linux; on macOS use Cmd in place of Ctrl.</p><h2 id="what-a-writing-home-is" tabindex="-1">What a writing home is <a class="header-anchor" href="#what-a-writing-home-is" aria-label="Permalink to &quot;What a writing home is&quot;">​</a></h2><p>A writing home is one folder on your computer that holds one story or many, in whatever shape you keep them: folders of markdown notes, an Obsidian vault, Word files, Scrivener projects, Fountain screenplays. You choose it at first run (see <a href="/guide/guide/getting-started#step-1-home">Getting started</a>), and from then on Leathercase opens on it.</p><p>Leathercase reads the home and never writes into your files. It keeps its own files in the same folder, beside your stories, for one reason: whatever carries your writing (a backup, Dropbox, Google Drive, iCloud Drive, OneDrive) carries Leathercase&#39;s files too, and a second computer that opens the folder finds every story as you left it.</p><p>Inside a home, a <strong>story</strong> is a folder Leathercase has been told is a story. Telling it is called declaring; see <a href="/guide/guide/declare-a-story">Declaring a story</a>. A folder of the home that was never declared is not read.</p><h2 id="what-a-home-holds" tabindex="-1">What a home holds <a class="header-anchor" href="#what-a-home-holds" aria-label="Permalink to &quot;What a home holds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>On disk</th><th>What it is</th><th>Who writes it</th></tr></thead><tbody><tr><td><code>Suite.md</code></td><td>A note at the home&#39;s root that marks the folder as a writing home and lists its stories, where each lives and which files it reads.</td><td>Leathercase writes the note once, then rewrites only the list of stories, between two marks. The rest of the note is yours to change. A <code>Suite.md</code> Leathercase did not write is left alone.</td></tr><tr><td><code>suite/</code></td><td>The home&#39;s own structured files: its manifest (<code>Library.json</code>), the author and pen names, the Writer Board&#39;s layout, described tags (<code>Tags.md</code>), and the daily snapshots in <code>suite/daily</code>.</td><td>Leathercase</td></tr><tr><td><code>Writer/</code></td><td>Your cards from the <a href="/guide/guide/writer-board">Writer Board</a>, one markdown note each, shared by every story in the home, and in <code>Writer/Templates/</code> the Graph templates you change or make. Made only when you make your first card or template.</td><td>Leathercase makes a card; what you write in it is yours</td></tr><tr><td>A <code>suite/</code> folder inside each story&#39;s folder</td><td>That story&#39;s settings (<code>Story.json</code>), export settings, layouts and snapshots as JSON; its Graph as markdown in <code>suite/Graph/</code> (the ties in <code>Ties.md</code>, a file for each tab); its writing and sentence logs as JSON Lines in <code>suite/logs/</code>, which also record when each scene last changed; and its threads (<code>StoryThreads.md</code>), plot grid (<code>PlotGrid.md</code>), comments and beat cards as markdown. All of it travels with the story&#39;s folder.</td><td>Leathercase</td></tr><tr><td>Everything else</td><td>Your stories and notes</td><td>You. Leathercase reads it and never writes into it.</td></tr></tbody></table><p>Every file Leathercase writes is a small markdown or JSON file you can open without Leathercase. A folder named <code>suite</code> is never read as prose, wherever it sits in the home. The full list is on <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><p>What belongs to this computer alone stays in the app&#39;s own data, never in the home: the list of homes you opened here, your preferences, the passage to resume, the connected agents. Removing a home clears that; see below.</p><h2 id="the-library" tabindex="-1">The Library <a class="header-anchor" href="#the-library" aria-label="Permalink to &quot;The Library&quot;">​</a></h2><p>The Library is the home&#39;s front page. Open it with <strong>Library</strong> in the sidebar, <code>Ctrl+1</code>, or by clicking the home&#39;s name at the start of the breadcrumb. It is also where Leathercase opens.</p><p><img src="'+g+'" alt="The Library of the sample home, with the resume card above the table of stories" width="755" height="752" loading="lazy"></p><h3 id="the-header" tabindex="-1">The header <a class="header-anchor" href="#the-header" aria-label="Permalink to &quot;The header&quot;">​</a></h3><p>The title <strong>Library</strong>, the number of stories (<strong>4 stories</strong>), and on the right <strong>New story</strong>, which opens the journey that declares a story. The same journey opens from the plus beside <strong>Stories</strong> in the sidebar and from <strong>Declare a story</strong> in the File menu.</p><h3 id="resume" tabindex="-1">Resume <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Resume&quot;">​</a></h3><p>When you last selected a passage in a story&#39;s manuscript, a card at the top brings you back to it. It reads <strong>Resume · The Lamp at Ferrol · The Ledger</strong>, then the passage itself in quotes, and when you selected it: <strong>selected today, 14:02</strong>, <strong>selected yesterday, 21:40</strong>, or the date.</p><ul><li><strong>Click the quote</strong> to open the manuscript at that passage.</li><li><strong>Open in Obsidian</strong> (or the app the story opens in, or <strong>Open in your default app</strong>) opens the file in your writing app, at that spot where the app can go there.</li><li><strong>Show in Plot grid</strong> opens the story&#39;s plot grid at that scene.</li></ul><p>The card is absent until you select a passage, and goes when its story is no longer declared.</p><h3 id="the-table-of-stories" tabindex="-1">The table of stories <a class="header-anchor" href="#the-table-of-stories" aria-label="Permalink to &quot;The table of stories&quot;">​</a></h3><p>One row per story, the one you worked on most recently first; stories never read come last. Click a row or the story&#39;s name to open it, on the view you last used.</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Story</strong></td><td>The story&#39;s mark and name, and under it how many files it reads, or <strong>not read yet</strong></td></tr><tr><td><strong>Source</strong></td><td>Where it is read from: <strong>Markdown</strong>, <strong>Obsidian</strong>, <strong>Word</strong>, <strong>Scrivener</strong> or <strong>Fountain</strong>, told from its files. A dashed <strong>Not read</strong> before the first reading.</td></tr><tr><td><strong>Words</strong></td><td>How many words the story holds now, or a dash before it is read</td></tr><tr><td><strong>Changed</strong></td><td>When its files last changed: <strong>today</strong>, <strong>yesterday</strong>, <strong>3 days ago</strong>, <strong>last week</strong>, then the date</td></tr><tr><td><strong>State</strong></td><td>A dot, a word for where the story stands, and a button that takes you to the fix</td></tr></tbody></table><p>The source is read from the files: Scrivener when a file sits in a <code>.scriv</code> project, otherwise the format most of the files are in; markdown inside an Obsidian vault is Obsidian.</p><h3 id="the-state-column" tabindex="-1">The State column <a class="header-anchor" href="#the-state-column" aria-label="Permalink to &quot;The State column&quot;">​</a></h3><p>The state compares what the story holds with the goal you set for it (a target in words, a deadline, a daily goal), set when you declare it or in its <a href="/guide/guide/story-settings">Story settings</a>.</p>',26)),e("table",f,[t[28]||(t[28]=e("thead",null,[e("tr",null,[e("th",{style:{"text-align":"center"}},"Library"),e("th",{style:{"text-align":"center"}},"Sidebar"),e("th",null,"State"),e("th",null,"What it means"),e("th",null,"Button")])],-1)),e("tbody",null,[e("tr",null,[e("td",w,[o(s,{tone:"hollow"})]),e("td",b,[o(s,{tone:"muted"})]),t[0]||(t[0]=e("td",null,[e("strong",null,"Not read yet")],-1)),t[1]||(t[1]=e("td",null,"The story has no words and no change seen yet",-1)),t[2]||(t[2]=e("td",null,[e("strong",null,"Open"),r(", which opens the story")],-1))]),e("tr",null,[e("td",k,[o(s,{tone:"ok"})]),e("td",S,[o(s,{tone:"ok"})]),t[3]||(t[3]=e("td",null,[e("strong",null,"Target met")],-1)),t[4]||(t[4]=e("td",null,"The story has reached its target in words",-1)),t[5]||(t[5]=e("td",null,"None",-1))]),e("tr",null,[e("td",v,[o(s,{tone:"ok"})]),e("td",T,[o(s,{tone:"ok"})]),t[6]||(t[6]=e("td",null,[e("strong",null,"On pace")],-1)),t[7]||(t[7]=e("td",null,"At the rate of the last days you will meet the deadline",-1)),t[8]||(t[8]=e("td",null,"None",-1))]),e("tr",null,[e("td",L,[o(s,{tone:"wait"})]),e("td",x,[o(s,{tone:"wait"})]),t[9]||(t[9]=e("td",null,[e("strong",null,"Behind")],-1)),t[10]||(t[10]=e("td",null,"At the rate of the last days you will miss the deadline",-1)),t[11]||(t[11]=e("td",null,[e("strong",null,"Desk"),r(", which opens the "),e("a",{href:"/guide/guide/desk"},"Desk")],-1))]),e("tr",null,[e("td",q,[o(s,{tone:"wait"})]),e("td",P,[o(s,{tone:"wait"})]),t[12]||(t[12]=e("td",null,[e("strong",null,"Deadline passed")],-1)),t[13]||(t[13]=e("td",null,"The deadline is behind you and the target is not met",-1)),t[14]||(t[14]=e("td",null,[e("strong",null,"Desk")],-1))]),e("tr",null,[e("td",A,[o(s,{tone:"wait"})]),e("td",N,[o(s,{tone:"muted"})]),t[15]||(t[15]=e("td",null,[e("strong",null,"Stalled")],-1)),t[16]||(t[16]=e("td",null,"No change in more than seven days",-1)),t[17]||(t[17]=e("td",null,[e("strong",null,"Desk")],-1))]),e("tr",null,[e("td",_,[o(s,{tone:"muted"})]),e("td",D,[o(s,{tone:"muted"})]),t[18]||(t[18]=e("td",null,[e("strong",null,"No target")],-1)),t[19]||(t[19]=e("td",null,"The story has no target in words",-1)),t[20]||(t[20]=e("td",null,[e("strong",null,"Set a goal"),r(", which opens its Story settings")],-1))]),e("tr",null,[e("td",W,[o(s,{tone:"muted"})]),e("td",O,[o(s,{tone:"muted"})]),t[21]||(t[21]=e("td",null,[e("strong",null,"No deadline")],-1)),t[22]||(t[22]=e("td",null,"A target, but no deadline to pace it against",-1)),t[23]||(t[23]=e("td",null,[e("strong",null,"Set a goal")],-1))]),e("tr",null,[e("td",C,[o(s,{tone:"wait"})]),t[24]||(t[24]=e("td",{style:{"text-align":"center"}},"the story's state",-1)),t[25]||(t[25]=e("td",null,[e("strong",null,"Open in not set")],-1)),t[26]||(t[26]=e("td",null,[r("Several apps on this computer open its files and none is chosen for "),e("strong",null,"Open in")],-1)),t[27]||(t[27]=e("td",null,[e("strong",null,"Choose"),r(", which opens "),e("strong",null,"Settings"),r(", "),e("strong",null,"Sources")],-1))])])]),t[30]||(t[30]=n('<p>The same state colours the small dot at the foot of each story&#39;s mark in the sidebar, so you can see how every story stands from any view. Rest the pointer on a story&#39;s name and it says its state in lower case: <strong>on pace</strong>, <strong>no target</strong>. The sidebar&#39;s dot is quieter than the table&#39;s in three places: a story not read yet and a stalled story show grey there, and <strong>Open in not set</strong> is a question for the Library only, so the sidebar keeps showing the story&#39;s state.</p><p><img src="'+m+'" alt="The sidebar&#39;s list of stories: Orchard Hours and The Salt Road with a grey dot (no target), The Lamp at Ferrol with an amber dot (behind), The Night Sleeper with a green dot (target met)" width="465" height="366" loading="lazy"></p><p><em>In the sample, The Night Sleeper was given a 2,000-word target, which its 2,194 words meet.</em></p><p>A line at the foot repeats the promise: <strong>your files are read, never written · what Leathercase adds is markdown in a folder you choose</strong>.</p><h3 id="a-home-with-no-stories" tabindex="-1">A home with no stories <a class="header-anchor" href="#a-home-with-no-stories" aria-label="Permalink to &quot;A home with no stories&quot;">​</a></h3><p>A home with no story says <strong>No stories in this home yet</strong>, explains what counts as one (a folder of markdown, a vault, a Scrivener project, Word files or a screenplay, inside your home&#39;s folder), and offers two buttons: <strong>New story</strong>, which opens the declare journey, and <strong>Show folder</strong>, which opens the home&#39;s folder in your system&#39;s file manager. A last line reminds you that the Writer library is shared by every story in the home and already open for ideas.</p><p><img src="'+u+'" alt="The Library of a home with no stories yet" width="632" height="287" loading="lazy"></p><h3 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h3><p>While the sample is open, a <strong>Start here</strong> column sits beside the Library. See <a href="/guide/guide/getting-started#start-here">Getting started</a>.</p><h2 id="more-than-one-home" tabindex="-1">More than one home <a class="header-anchor" href="#more-than-one-home" aria-label="Permalink to &quot;More than one home&quot;">​</a></h2><p>You can keep more than one home: one for a pen name, one for a series, one for poems. Each has its own stories, its own Writer Board and its own Desk.</p><p><strong>Adding a home.</strong> Any of these opens your system&#39;s folder dialog, titled <strong>Open a library</strong>:</p><ul><li><strong>Add a writing home…</strong> in the home switcher at the top of the sidebar;</li><li><strong>Add a writing home</strong> in the File menu, or in the find field;</li><li><strong>Add a writing home…</strong> beside <strong>Other homes</strong> in <strong>Settings</strong>, <strong>Storage</strong>.</li></ul><p>Pick the folder. Leathercase writes <code>Suite.md</code> and <code>suite/</code> in it, adds it to this computer&#39;s list of homes and switches to it. A folder that is already a home, made on this or another computer, opens with its stories as they were. A new home starts with no stories: declare them from its Library. Adding a home does not walk you through first run again.</p><p>Some folders cannot be a home, and Leathercase says why: the root of a drive, your whole home folder (choose the folder inside it that holds your stories), a system folder, or the folder where Leathercase keeps its own data. A folder is known however its path is spelled, so the same folder is never listed twice.</p><p>If another home already has the folder&#39;s name, the new home is named apart, with the folder it sits in: a second <code>storytelling</code> inside <code>Drafts</code> becomes <strong>storytelling (Drafts)</strong>. Settings opens at its name so you can give it one of your own.</p><p><strong>Switching homes.</strong> Click the home switcher and pick another home; the open one is ticked and marked <strong>current</strong>. Every home shows its folder by its last two folders, such as <code>…/Drafts/storytelling</code>. Or use <strong>Switch</strong> beside a home in <strong>Settings</strong>, <strong>Storage</strong>, <strong>Other homes</strong>. Leathercase opens on the home you used last.</p><p><strong>Naming a home.</strong> Choose <strong>Name and look…</strong> in the home switcher, or open <strong>Settings</strong>, <strong>Storage</strong>, <strong>This home</strong>. Type the home&#39;s name and press Enter, or leave the field; Esc puts the old name back. Pick a colour for its tile, <strong>Accent</strong> or one of nine, and an icon to show on it in place of the name&#39;s first letter, one of twenty-four, or <strong>First letter</strong> to go back. The name, colour and icon are kept in the home&#39;s <code>suite/Library.json</code>, so every computer the folder syncs to shows the home the same way. Renaming a home does not change <code>Suite.md</code>, which is yours to edit.</p>',18)),o(a,{name:"homes-and-stories-switch-home",caption:"The home switcher lists the homes, adds one, and switches to another"}),t[31]||(t[31]=n('<h2 id="settings-storage" tabindex="-1">Settings, Storage <a class="header-anchor" href="#settings-storage" aria-label="Permalink to &quot;Settings, Storage&quot;">​</a></h2><p><strong>Settings</strong>, <strong>Storage</strong> describes the open home. Its file name in the corner is <code>preferences.json</code>, since most of what it lists is this computer&#39;s; the home&#39;s name and look are the exception, kept in <code>suite/Library.json</code>.</p><p><img src="'+c+'" alt="Settings, Storage, with the home&#39;s folder, what it holds, the other homes and the remove buttons" width="547" height="1100" loading="lazy"></p><ul><li><strong>This home</strong>: the home&#39;s <strong>Name</strong>, <strong>Colour</strong> and <strong>Icon</strong>, kept in the home&#39;s folder. See <a href="#more-than-one-home">Naming a home</a> above.</li><li><strong>Writing home</strong>: the folder&#39;s path, and <strong>Show folder</strong> to open it in your file manager.</li><li><strong>Sync</strong>: who carries the folder. <strong>local</strong> with <strong>No sync tool holds this folder; it lives on this computer only.</strong>, or <strong>detected</strong> with <strong>Dropbox carries this folder. Leathercase never uploads anything itself.</strong></li><li><strong>Daily snapshots</strong>: a copy of every <code>suite</code> folder, kept in <code>suite/daily</code> for 14 days, with how many days are kept, their size and the latest day. Manuscripts are never copied. <strong>Show</strong> opens the folder.</li><li><strong>In this home</strong>: <code>Suite.md</code>, <code>suite/</code>, <code>Writer/</code> and one <code>suite/</code> per story, each with a line on what it holds.</li><li><strong>Other homes</strong>: every other home on this computer, each with <strong>Remove…</strong> and <strong>Switch</strong>, or <strong>No other home</strong> when there is none. <strong>Add a writing home…</strong> sits beside the heading.</li><li><strong>Remove this home</strong>: <strong>Delete writing home</strong> and <strong>Purge writing home</strong>, below.</li><li>When a sync tool made conflicted copies of Leathercase&#39;s files, a group lists them with <strong>Compare</strong>, <strong>Keep the copy</strong> and <strong>Keep this computer&#39;s</strong>. See <a href="/guide/reference/faq">FAQ and troubleshooting</a>.</li></ul><h2 id="removing-a-home" tabindex="-1">Removing a home <a class="header-anchor" href="#removing-a-home" aria-label="Permalink to &quot;Removing a home&quot;">​</a></h2><p>There are two ways to let a home go. Neither ever touches your prose.</p><table tabindex="0"><thead><tr><th></th><th><strong>Delete</strong></th><th><strong>Purge</strong></th></tr></thead><tbody><tr><td>Takes the home off this computer&#39;s list of homes</td><td>Yes</td><td>Yes</td></tr><tr><td>Clears what this computer kept of it: the passage to resume, the capture target, the agents&#39; access to it, the mate&#39;s memory of it</td><td>Yes</td><td>Yes</td></tr><tr><td>Moves Leathercase&#39;s files in the folder to the trash</td><td>No</td><td>Yes: <code>Suite.md</code>, every <code>suite/</code> folder, and the cards Leathercase made in <code>Writer/</code></td></tr><tr><td>Your manuscripts and your own notes</td><td>Stay</td><td>Stay</td></tr><tr><td>Opening the folder again later</td><td>Takes the home up as it was</td><td>Starts a new home</td></tr></tbody></table><h3 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h3><ol><li>Open <strong>Settings</strong>, <strong>Storage</strong>.</li><li>Beside <strong>Delete writing home</strong>, press <strong>Delete…</strong>. For another home, press <strong>Remove…</strong> beside it under <strong>Other homes</strong>.</li><li>The dialog, <strong>Delete Stories?</strong>, says that the home leaves this computer&#39;s list of homes with what this computer kept of it, and that <strong>nothing in</strong> the folder <strong>changes</strong>.</li><li>Press <strong>Delete home</strong>, or <strong>Cancel</strong>.</li></ol><p>Deleting the open home lands you on your next home, or on first run when it was the only one. Deleting another home leaves you where you are.</p><h3 id="purge" tabindex="-1">Purge <a class="header-anchor" href="#purge" aria-label="Permalink to &quot;Purge&quot;">​</a></h3><ol><li>Open <strong>Settings</strong>, <strong>Storage</strong>, and press <strong>Purge…</strong> beside <strong>Purge writing home</strong>. Or open the Delete dialog and choose <strong>Purge</strong> in the switch at its top.</li><li>The dialog, <strong>Purge Stories?</strong>, reads the folder (<strong>Reading the folder…</strong>), then lists under <strong>Moves to the trash</strong> every file and folder Leathercase made there, for example <code>Suite.md</code>, <code>suite/</code>, <code>The Lamp at Ferrol/suite/</code> and the cards in <code>Writer/</code>. When Leathercase made nothing there it says so.</li><li>When a sync tool carries the folder, a rose note warns that <strong>Dropbox syncs this folder: these files will leave every device that syncs it.</strong></li><li>Under <strong>Left where they are</strong>, it lists folders you chose elsewhere for a story&#39;s notes from Leathercase. They may hold your own notes too, so Leathercase leaves them; delete what you no longer want by hand. Any other folder named <code>suite</code> that Leathercase did not make is left too, and so is any note in <code>Writer/</code> that Leathercase did not write.</li><li><strong>Type Stories to confirm</strong>: type the home&#39;s name exactly. <strong>Purge home</strong> stays greyed out until you do.</li><li>Press <strong>Purge home</strong>.</li></ol><p>Everything goes to your system&#39;s trash, not straight to deletion, so you can take it back from there.</p>',13)),o(a,{name:"homes-and-stories-purge",caption:"Purge lists Leathercase's files, warns of the sync, and waits for the home's name"}),t[32]||(t[32]=n('<h3 id="the-sample" tabindex="-1">The sample <a class="header-anchor" href="#the-sample" aria-label="Permalink to &quot;The sample&quot;">​</a></h3><p>The sample is a home too. <strong>Leave the sample</strong>, in the home switcher or at the foot of Start here, deletes it the same way and also removes its copy from the app&#39;s data. See <a href="/guide/guide/getting-started#start-over-and-leave-the-sample">Getting started</a>.</p><h3 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h3><p>Uninstalling the app leaves every home as it is, Leathercase&#39;s files included, on purpose. Purge each home first if you want them gone. See <a href="/guide/reference/updates">Updates and uninstalling</a>.</p><h2 id="a-story-whose-folder-moved" tabindex="-1">A story whose folder moved <a class="header-anchor" href="#a-story-whose-folder-moved" aria-label="Permalink to &quot;A story whose folder moved&quot;">​</a></h2><p>If you move or rename a story&#39;s folder, or its drive is not mounted, the Desk says <strong>The story&#39;s folder was not found</strong>, with <strong>The Lamp at Ferrol · moved, renamed or not mounted</strong>, and offers <strong>Find it</strong>. Press it and pick the folder where the story is now, inside the same home. The story&#39;s settings travel inside its <code>suite/</code> folder, so Leathercase takes the story up from there with everything you set. While the folder is missing, the heartbeat of an open story says the folder cannot be read and the views show the last reading. See <a href="/guide/guide/desk">The Desk</a>.</p><h2 id="renamed-notes" tabindex="-1">Renamed notes <a class="header-anchor" href="#renamed-notes" aria-label="Permalink to &quot;Renamed notes&quot;">​</a></h2><p>A character, place, item, faction or event is known by its note, and its name is the note&#39;s file name. So when you rename <code>Characters/Nora.md</code> to <code>Characters/Nora Vidal.md</code> in your own app, Leathercase first sees one note gone and one new. It compares each reading with the last, and when the change looks like a rename it asks you.</p><p><img src="'+p+'" alt="The rename question over the story&#39;s views, with its two answers" width="1130" height="140" loading="lazy"></p><h3 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h3><p>Over the story&#39;s views, a strip asks one rename at a time:</p><p><strong>Nora looks renamed to Nora Vidal: its note&#39;s text is the same. Should Leathercase&#39;s own files follow the new name?</strong></p><p>The reason given is one of three:</p><ul><li><strong>its note&#39;s text is the same</strong>;</li><li><strong>the new note keeps Nora as another name</strong> (in its <code>aliases:</code>);</li><li><strong>it is the only note gone and the only one new in its folder</strong>.</li></ul><p>When more renames wait, the strip says <strong>2 more wait</strong>. The same questions are listed under <strong>What looks off</strong> on <a href="/guide/guide/how-a-story-is-read#renames-and-names-leathercase-s-files-still-use">How this story is read</a>.</p><h3 id="yes-follow-the-new-name" tabindex="-1">Yes, follow the new name <a class="header-anchor" href="#yes-follow-the-new-name" aria-label="Permalink to &quot;Yes, follow the new name&quot;">​</a></h3><p><strong>Yes, follow Nora Vidal</strong> makes Leathercase&#39;s own files follow the new name:</p><ul><li>the Graph&#39;s ties in <code>Graph/Ties.md</code> and the roles in its tabs, and the relationships drawn on the old story map, in <code>Relationships.md</code>;</li><li>the accents in <code>Accents.md</code> and the threads in <code>StoryThreads.md</code>;</li><li>Leathercase&#39;s own note beside hers, which becomes <code>suite/Characters/Nora Vidal.md</code>;</li><li>any thread strip you hid.</li></ul><p><code>Story.json</code> keeps &quot;Nora&quot; as another name for Nora Vidal, so the prose that still says Nora finds her. The question goes. Your notes are not written: the rename you made is the only change to them.</p><h3 id="no-they-are-different" tabindex="-1">No, they are different <a class="header-anchor" href="#no-they-are-different" aria-label="Permalink to &quot;No, they are different&quot;">​</a></h3><p><strong>No, they are different</strong> leaves Leathercase&#39;s files as they were, and Leathercase never asks about that pair again.</p><h3 id="names-leathercase-s-files-still-use" tabindex="-1">Names Leathercase&#39;s files still use <a class="header-anchor" href="#names-leathercase-s-files-still-use" aria-label="Permalink to &quot;Names Leathercase&#39;s files still use&quot;">​</a></h3><p>When one of Leathercase&#39;s files names someone no note of the story answers to any more (after a rename you said no to, or a note you deleted), <strong>How this story is read</strong> lists it: <strong>Relationships.md names Nora, and no note of the story answers to that name.</strong> It offers <strong>Open Relationships.md</strong>, or <strong>Open the story&#39;s settings</strong> when the name is in <code>Story.json</code>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/getting-started">Getting started</a></li><li><a href="/guide/guide/declare-a-story">Declaring a story</a></li><li><a href="/guide/guide/how-a-story-is-read">How a story is read</a></li><li><a href="/guide/guide/desk">The Desk</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>',25))])}const B=h(y,[["render",R]]);export{G as __pageData,B as default};
